std::lock_guard<std::mutex> lock(mutex_);

// Existing-key check FIRST. This is what lets an identical retry still
// succeed when the store is already full: we find the key and confirm
// the payload matches before ever consulting Capacity.
for (std::size_t i = 0; i < count_; ++i) {
    const std::optional<study_net::MatchRecord>& slot = rows_[i];
    if (slot.has_value() && slot->key == record.key) {
        if (*slot == record) {
            // Idempotent accept: same key, same payload. Row is reported
            // as a positive, one-based index.
            return PutResult{
                PutStatus::accepted,
                study_net::Receipt{record.key, i + 1, record.player_a, record.player_b}};
        }
        // Same key, different payload. Never overwrite: reject.
        return PutResult{PutStatus::conflict, study_net::Receipt{}};
    }
}

    // New key. Only now does capacity matter.
    if (count_ == Capacity) {
        return PutResult{PutStatus::full, study_net::Receipt{}};
    }

    // Copy the record into the next free row without any allocation.
    rows_[count_] = record;
    ++count_;
    // count_ is now the one-based row of the record we just stored.
    return PutResult{
        PutStatus::accepted,
        study_net::Receipt{record.key, count_, record.player_a, record.player_b}};
}

std::optional<study_net::MatchRecord> lookup(std::uint64_t key) const {
    std::lock_guard<std::mutex> lock(mutex_);
    for (std::size_t i = 0; i < count_; ++i) {
        const std::optional<study_net::MatchRecord>& slot = rows_[i];
        if (slot.has_value() && slot->key == key) {
            return *slot;  // copy taken under the lock
        }
    }
    return std::nullopt;
}

inline Json record_json(const study_net::MatchRecord& r) {
    return {{"key",r.key},{"round",r.round},{"player_a",r.player_a},{"player_b",r.player_b},
            {"ticks",r.ticks},{"score_a",r.score_a},{"score_b",r.score_b},
            {"lines_a",r.lines_a},{"lines_b",r.lines_b},{"winner",static_cast<unsigned>(r.winner)}};
}

inline std::optional<std::uint64_t> number(const Json& object,const char* name) {
    const auto it=object.find(name);
    if(it==object.end() || !it->is_number_integer())return std::nullopt;
    if(it->is_number_unsigned())return it->get<std::uint64_t>();
    const auto value=it->get<std::int64_t>();
    return value<0 ? std::nullopt : std::optional<std::uint64_t>(value);
}

http.Post("/study/v1/matches",[&store](const httplib::Request& req,httplib::Response& res){
    const auto record=study_meta::parse_record(req.body);
    if(!record){res.status=400;res.set_content("{\"error\":\"invalid\"}","application/json");return;}
    const auto result=store.put(*record);
    using Status=study_meta::PutStatus;
    if(result.status==Status::accepted) {
        res.set_content(study_meta::receipt_json(result.receipt).dump(),"application/json");
    }else {
        res.status=result.status==Status::conflict ? 409 : result.status==Status::full ? 503 : 400;
        res.set_content("{\"error\":\"not_accepted\"}","application/json");
    }
});

